-- ============================================================================
-- Migration 1103: Rapid Prototyping machines -- their specs as the additive engine reads them, their lasers' cost, and India rates
-- ============================================================================
-- Generated by scripts/generate-rapid-prototyping-machines-migration.js; re-run it and diff instead of editing.
--
-- Rapid Prototyping is priced by the additive engine in its own domain (costing/additive/additive-domain.ts). Migration 862 seeded its 25
-- machines for the USA only, under the column names of memory/Rapid prototyping's machine files, which differ from the ones the engine reads
-- (and memory/Additive Manufacturing's files use) for the same machines:
--   Printing       layer_speed -> layer_speed_m_per_s, layer_thickness -> layer_thickness_mm, scanning_speed -> scanning_width_mm (the
--                  Rapid Prototyping file heads the column "Scanning Speed"; it is the print head's width: 185 mm on the ProJet CP3000, the
--                  value memory/Additive Manufacturing's file gives as "Scanning Width (mm)")
--   Resin Curing   scanning_speed -> scanning_speed_mm_per_s, wiper_speed -> wiper_speed_mm_per_s
-- Each laser's cost per hour (memory/Rapid prototyping/Lookup: laser_cost_per_hour for the sinterers, laser_replacement for the
-- stereolithography machines) is written as laser_cost_per_hour_usd_per_hr, and the machines' flags (can_use_laserform_materials, can_use_v_flash_material, can_cure_laserform_materials, requires_external_nitrogen, requires_nitrogen, is_preferred) as booleans.
--
-- India twins. Source: memory/Countries data/India_XML_Data_.csv, commodity "Rapid Prototyping": each machine's direct and indirect overhead
-- rate (USD/hr, rounded to cents). Labour: the India rate of wage grade 2 - Metal (every Rapid Prototyping process's grade,
-- memory/Rapid prototyping/wage_grade_associations), 1.65 USD/hr, the value the India rows of that grade already carry, written to
-- usd_labor_rate_per_hr AND usd_lhr_total (the column the machine selector reads). 25 machines, each matched by machine class and exact
-- name to its USA row (whose specs, normalised above, it copies):
--   Cleaning          1 machine(s)
--   Laser Sintering   7 machine(s)
--   Part Curing       5 machine(s)
--   Printing          7 machine(s)
--   Resin Curing      5 machine(s)
--
-- Idempotent: the spec renames keep a key already renamed; an India row already present for its class and name is skipped.
-- Verify: SELECT location, machine_class, count(*) FROM mhr_records WHERE machine_class LIKE 'rapid_prototyping_%' GROUP BY 1, 2 ORDER BY 1, 2;
--   -- expect USA 25 rows (5 classes), India 25 rows (5 classes).
-- ============================================================================

-- ── The specs ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
UPDATE mhr_records m SET
  specs = (
    SELECT COALESCE(jsonb_object_agg(COALESCE(p.rename ->> e.key, e.key), e.value), '{}'::jsonb)
    FROM jsonb_each(m.specs) e
    WHERE NOT (p.rename ? e.key AND m.specs ? (p.rename ->> e.key))
  ) || p.set_specs,
  updated_at = now()
FROM (VALUES
  ($str$rapid_prototyping_laser_sintering$str$, $str$Formiga P100$str$, $str${}$str$::jsonb, $str${"laser_cost_per_hour_usd_per_hr":2.76}$str$::jsonb),
  ($str$rapid_prototyping_laser_sintering$str$, $str$Sinterstation HiQ$str$, $str${}$str$::jsonb, $str${"laser_cost_per_hour_usd_per_hr":2.76}$str$::jsonb),
  ($str$rapid_prototyping_laser_sintering$str$, $str$EOSINT P395$str$, $str${}$str$::jsonb, $str${"laser_cost_per_hour_usd_per_hr":3.52}$str$::jsonb),
  ($str$rapid_prototyping_laser_sintering$str$, $str$Sinterstation 60$str$, $str${}$str$::jsonb, $str${"laser_cost_per_hour_usd_per_hr":3.95}$str$::jsonb),
  ($str$rapid_prototyping_laser_sintering$str$, $str$Sinterstation 140$str$, $str${}$str$::jsonb, $str${"laser_cost_per_hour_usd_per_hr":3.95}$str$::jsonb),
  ($str$rapid_prototyping_laser_sintering$str$, $str$Sinterstation 230$str$, $str${}$str$::jsonb, $str${"laser_cost_per_hour_usd_per_hr":6.4}$str$::jsonb),
  ($str$rapid_prototyping_laser_sintering$str$, $str$EOSINT P760$str$, $str${}$str$::jsonb, $str${"laser_cost_per_hour_usd_per_hr":7.05}$str$::jsonb),
  ($str$rapid_prototyping_printing$str$, $str$V-Flash$str$, $str${"layer_speed":"layer_speed_m_per_s","layer_thickness":"layer_thickness_mm","scanning_speed":"scanning_width_mm"}$str$::jsonb, $str${}$str$::jsonb),
  ($str$rapid_prototyping_printing$str$, $str$ProJet HD3000$str$, $str${"layer_speed":"layer_speed_m_per_s","layer_thickness":"layer_thickness_mm","scanning_speed":"scanning_width_mm"}$str$::jsonb, $str${}$str$::jsonb),
  ($str$rapid_prototyping_printing$str$, $str$ProJet CP3000$str$, $str${"layer_speed":"layer_speed_m_per_s","layer_thickness":"layer_thickness_mm","scanning_speed":"scanning_width_mm"}$str$::jsonb, $str${}$str$::jsonb),
  ($str$rapid_prototyping_printing$str$, $str$ProJet 5000$str$, $str${"layer_speed":"layer_speed_m_per_s","layer_thickness":"layer_thickness_mm","scanning_speed":"scanning_width_mm"}$str$::jsonb, $str${}$str$::jsonb),
  ($str$rapid_prototyping_printing$str$, $str$Eden500V$str$, $str${"layer_speed":"layer_speed_m_per_s","layer_thickness":"layer_thickness_mm","scanning_speed":"scanning_width_mm"}$str$::jsonb, $str${}$str$::jsonb),
  ($str$rapid_prototyping_printing$str$, $str$Eden350$str$, $str${"layer_speed":"layer_speed_m_per_s","layer_thickness":"layer_thickness_mm","scanning_speed":"scanning_width_mm"}$str$::jsonb, $str${}$str$::jsonb),
  ($str$rapid_prototyping_printing$str$, $str$Eden250$str$, $str${"layer_speed":"layer_speed_m_per_s","layer_thickness":"layer_thickness_mm","scanning_speed":"scanning_width_mm"}$str$::jsonb, $str${}$str$::jsonb),
  ($str$rapid_prototyping_resin_curing$str$, $str$Viper$str$, $str${"scanning_speed":"scanning_speed_mm_per_s","wiper_speed":"wiper_speed_mm_per_s"}$str$::jsonb, $str${"laser_cost_per_hour_usd_per_hr":3.18}$str$::jsonb),
  ($str$rapid_prototyping_resin_curing$str$, $str$iPro 8000$str$, $str${"scanning_speed":"scanning_speed_mm_per_s","wiper_speed":"wiper_speed_mm_per_s"}$str$::jsonb, $str${"laser_cost_per_hour_usd_per_hr":7.7}$str$::jsonb),
  ($str$rapid_prototyping_resin_curing$str$, $str$Accura 22$str$, $str${"scanning_speed":"scanning_speed_mm_per_s","wiper_speed":"wiper_speed_mm_per_s"}$str$::jsonb, $str${"laser_cost_per_hour_usd_per_hr":7.7}$str$::jsonb),
  ($str$rapid_prototyping_resin_curing$str$, $str$iPro 9000$str$, $str${"scanning_speed":"scanning_speed_mm_per_s","wiper_speed":"wiper_speed_mm_per_s"}$str$::jsonb, $str${"laser_cost_per_hour_usd_per_hr":7.7}$str$::jsonb),
  ($str$rapid_prototyping_resin_curing$str$, $str$iPro 9000XL$str$, $str${"scanning_speed":"scanning_speed_mm_per_s","wiper_speed":"wiper_speed_mm_per_s"}$str$::jsonb, $str${"laser_cost_per_hour_usd_per_hr":7.7}$str$::jsonb)
) AS p(machine_class, machine_name, rename, set_specs)
WHERE m.machine_class = p.machine_class AND m.machine_name = p.machine_name AND m.specs IS NOT NULL;

UPDATE mhr_records m SET
  specs = m.specs || (
    SELECT jsonb_object_agg(f.key, to_jsonb(lower(m.specs ->> f.key) = 'true'))
    FROM unnest(ARRAY[$str$can_use_laserform_materials$str$, $str$can_use_v_flash_material$str$, $str$can_cure_laserform_materials$str$, $str$requires_external_nitrogen$str$, $str$requires_nitrogen$str$, $str$is_preferred$str$]) AS f(key)
    WHERE m.specs ? f.key
  ),
  updated_at = now()
WHERE m.machine_class LIKE 'rapid_prototyping_%' AND m.specs ?| ARRAY[$str$can_use_laserform_materials$str$, $str$can_use_v_flash_material$str$, $str$can_cure_laserform_materials$str$, $str$requires_external_nitrogen$str$, $str$requires_nitrogen$str$, $str$is_preferred$str$];

-- ── India twins ───────────────────────────────────────────────────────────────────────────────────────────────────────────────────
DO $rapid_prototyping_machines$
DECLARE
  cols text; sel text; r record; usa_id uuid; n integer := 0; missing text[] := '{}';
BEGIN
  SELECT
    string_agg(quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position),
    string_agg(
      CASE c.column_name
        WHEN 'location'                                THEN '$5'
        WHEN 'country_code'                            THEN '$6'
        WHEN 'direct_overhead_rate'                    THEN '$2'
        WHEN 'indirect_overhead_rate'                  THEN '$3'
        WHEN 'benchmark_direct_overhead_rate_usd_hr'   THEN '$2'
        WHEN 'benchmark_indirect_overhead_rate_usd_hr' THEN '$3'
        WHEN 'total_machine_hour_rate'                 THEN 'ROUND(($2 + $3)::numeric, 2)'
        WHEN 'mhr_usd_per_hour'                        THEN 'ROUND(($2 + $3)::numeric, 2)'
        WHEN 'usd_labor_rate_per_hr'                   THEN '$4'
        WHEN 'usd_lhr_total'                           THEN '$4'
        WHEN 'benchmark_labor_rate_usd_hr'             THEN '$4'
        WHEN 'benchmark_source_key'                    THEN '$7'
        WHEN 'id'                                      THEN 'gen_random_uuid()'
        WHEN 'created_at'                              THEN 'now()'
        WHEN 'updated_at'                              THEN 'now()'
        ELSE 'usa_row.' || quote_ident(c.column_name)
      END, ', ' ORDER BY c.ordinal_position
    )
  INTO cols, sel
  FROM information_schema.columns c
  WHERE c.table_schema = 'public' AND c.table_name = 'mhr_records' AND c.is_generated = 'NEVER';

  -- (machine class, machine name, labour, direct, indirect, source key)
  FOR r IN SELECT * FROM (VALUES
  ($str$rapid_prototyping_cleaning$str$, $str$Default Cleaning$str$, 1.65, 0.12, 1, $str$Cleaning:Default Cleaning:India$str$),
  ($str$rapid_prototyping_laser_sintering$str$, $str$EOSINT P395$str$, 1.65, 12.12, 0.99, $str$Laser Sintering:EOSINT P395:India$str$),
  ($str$rapid_prototyping_laser_sintering$str$, $str$EOSINT P760$str$, 1.65, 29.31, 1.07, $str$Laser Sintering:EOSINT P760:India$str$),
  ($str$rapid_prototyping_laser_sintering$str$, $str$Formiga P100$str$, 1.65, 6.42, 0.94, $str$Laser Sintering:Formiga P100:India$str$),
  ($str$rapid_prototyping_laser_sintering$str$, $str$Sinterstation 140$str$, 1.65, 13.65, 1.14, $str$Laser Sintering:Sinterstation 140:India$str$),
  ($str$rapid_prototyping_laser_sintering$str$, $str$Sinterstation 230$str$, 1.65, 19.8, 1.14, $str$Laser Sintering:Sinterstation 230:India$str$),
  ($str$rapid_prototyping_laser_sintering$str$, $str$Sinterstation 60$str$, 1.65, 13.13, 0.99, $str$Laser Sintering:Sinterstation 60:India$str$),
  ($str$rapid_prototyping_laser_sintering$str$, $str$Sinterstation HiQ$str$, 1.65, 10.43, 1.05, $str$Laser Sintering:Sinterstation HiQ:India$str$),
  ($str$rapid_prototyping_part_curing$str$, $str$AaroCure Oven$str$, 1.65, 0.75, 0.94, $str$Part Curing:AaroCure Oven:India$str$),
  ($str$rapid_prototyping_part_curing$str$, $str$LaserForm Oven$str$, 1.65, 3.16, 1.08, $str$Part Curing:LaserForm Oven:India$str$),
  ($str$rapid_prototyping_part_curing$str$, $str$No Curing Needed$str$, 1.65, 0, 0, $str$Part Curing:No Curing Needed:India$str$),
  ($str$rapid_prototyping_part_curing$str$, $str$ProCure 350$str$, 1.65, 0.56, 0.91, $str$Part Curing:ProCure 350:India$str$),
  ($str$rapid_prototyping_part_curing$str$, $str$ProCure 750$str$, 1.65, 0.92, 1.05, $str$Part Curing:ProCure 750:India$str$),
  ($str$rapid_prototyping_printing$str$, $str$Eden250$str$, 1.65, 2.43, 0.94, $str$Printing:Eden250:India$str$),
  ($str$rapid_prototyping_printing$str$, $str$Eden350$str$, 1.65, 4.49, 1.01, $str$Printing:Eden350:India$str$),
  ($str$rapid_prototyping_printing$str$, $str$Eden500V$str$, 1.65, 5.61, 1.01, $str$Printing:Eden500V:India$str$),
  ($str$rapid_prototyping_printing$str$, $str$ProJet 5000$str$, 1.65, 5.72, 1.02, $str$Printing:ProJet 5000:India$str$),
  ($str$rapid_prototyping_printing$str$, $str$ProJet CP3000$str$, 1.65, 2.45, 0.97, $str$Printing:ProJet CP3000:India$str$),
  ($str$rapid_prototyping_printing$str$, $str$ProJet HD3000$str$, 1.65, 2.82, 0.97, $str$Printing:ProJet HD3000:India$str$),
  ($str$rapid_prototyping_printing$str$, $str$V-Flash$str$, 1.65, 0.44, 0.92, $str$Printing:V-Flash:India$str$),
  ($str$rapid_prototyping_resin_curing$str$, $str$Accura 22$str$, 1.65, 22.23, 1.07, $str$Resin Curing:Accura 22:India$str$),
  ($str$rapid_prototyping_resin_curing$str$, $str$iPro 8000$str$, 1.65, 16.11, 1.02, $str$Resin Curing:iPro 8000:India$str$),
  ($str$rapid_prototyping_resin_curing$str$, $str$iPro 9000$str$, 1.65, 21.68, 1.06, $str$Resin Curing:iPro 9000:India$str$),
  ($str$rapid_prototyping_resin_curing$str$, $str$iPro 9000XL$str$, 1.65, 36.79, 1.06, $str$Resin Curing:iPro 9000XL:India$str$),
  ($str$rapid_prototyping_resin_curing$str$, $str$Viper$str$, 1.65, 7.11, 0.93, $str$Resin Curing:Viper:India$str$)
  ) AS v(machine_class, machine_name, labor, direct, indirect, source_key)
  LOOP
    SELECT id INTO usa_id FROM mhr_records
    WHERE location = 'USA' AND machine_class = r.machine_class AND machine_name = r.machine_name
    LIMIT 1;
    IF usa_id IS NULL THEN
      missing := array_append(missing, r.machine_class || ':' || r.machine_name);
      CONTINUE;
    END IF;
    IF EXISTS (SELECT 1 FROM mhr_records m WHERE m.location = 'India' AND m.machine_class = r.machine_class AND m.machine_name = r.machine_name) THEN
      CONTINUE;
    END IF;
    EXECUTE format('INSERT INTO mhr_records (%s) SELECT %s FROM mhr_records usa_row WHERE usa_row.id = $1', cols, sel)
      USING usa_id, r.direct, r.indirect, r.labor, 'India', 'IN', r.source_key;
    n := n + 1;
  END LOOP;

  RAISE NOTICE 'Rapid Prototyping India rows inserted: %', n;
  IF array_length(missing, 1) > 0 THEN
    RAISE EXCEPTION 'Rapid Prototyping machines with no USA row (migration 862): %', missing;
  END IF;
END $rapid_prototyping_machines$;

NOTIFY pgrst, 'reload schema';
